-- Contact form messages. The contact page used to show "sent" without saving or sending anything.
-- A message is saved first; the email to info@ is a separate, tracked step, so a failed email never
-- loses the message and the page never claims an email was sent when it was not.

CREATE TABLE IF NOT EXISTS public.contact_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Generated by the browser per form; a double click or resubmission reuses the same row.
  request_id uuid NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 120),
  phone text NOT NULL CHECK (char_length(phone) BETWEEN 9 AND 20),
  email text NOT NULL CHECK (char_length(email) BETWEEN 3 AND 160),
  message text NOT NULL CHECK (char_length(message) BETWEEN 2 AND 4000),
  email_status text NOT NULL DEFAULT 'pending' CHECK (email_status IN ('pending', 'sent', 'failed')),
  email_attempts int NOT NULL DEFAULT 0,
  email_sent_at timestamptz,
  handled_at timestamptz
);
CREATE INDEX IF NOT EXISTS contact_messages_created_idx ON public.contact_messages (created_at DESC);

-- Written only by the contact-message Edge Function (service role). Staff read through the admin role.
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.contact_messages FROM anon, authenticated;
GRANT SELECT, UPDATE ON public.contact_messages TO authenticated;
GRANT ALL ON public.contact_messages TO service_role;
DROP POLICY IF EXISTS "admins read contact messages" ON public.contact_messages;
CREATE POLICY "admins read contact messages" ON public.contact_messages
  FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS "admins mark contact messages handled" ON public.contact_messages;
CREATE POLICY "admins mark contact messages handled" ON public.contact_messages
  FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));

-- The Edge Function reuses the rate limiter from 0008 (salted IP hash buckets).
GRANT EXECUTE ON FUNCTION public.hit_rate_limit(text, int, interval) TO service_role;
